#!/usr/bin/env python3
"""
Multi-Modal Processor pentru SENTINEL_PRIME
Procesează imagini, audio, video, documente, URLs
"""
import json
import os
import hashlib
from datetime import datetime
from pathlib import Path
from typing import Dict, Optional, List


WORKSPACE = Path(os.environ.get('WORKSPACE_ROOT', 'C:\\Users\\apviz\\.minimax-agent\\projects\\SENTINEL_PRIME'))
METADATA_FILE = WORKSPACE / '09_LOGS' / 'multimodal_metadata.json'


IMAGE_FORMATS = {'.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.bmp'}
AUDIO_FORMATS = {'.mp3', '.wav', '.ogg', '.m4a', '.flac', '.aac'}
VIDEO_FORMATS = {'.mp4', '.mov', '.avi', '.mkv', '.webm', '.flv'}
DOC_FORMATS = {'.pdf', '.docx', '.xlsx', '.pptx', '.md', '.txt', '.rtf'}


class MultiModalProcessor:
    """Procesează multiple tipuri de input"""

    def __init__(self, workspace: Path = WORKSPACE):
        self.workspace = workspace
        self.processed = []
        METADATA_FILE.parent.mkdir(parents=True, exist_ok=True)
        if not METADATA_FILE.exists():
            METADATA_FILE.write_text('[]', encoding='utf-8')

    def detect_type(self, path_or_url: str) -> str:
        """Detectează tipul de input"""
        if path_or_url.startswith('http://') or path_or_url.startswith('https://'):
            return 'url'
        if not os.path.exists(path_or_url):
            return 'unknown'

        ext = Path(path_or_url).suffix.lower()
        if ext in IMAGE_FORMATS:
            return 'image'
        elif ext in AUDIO_FORMATS:
            return 'audio'
        elif ext in VIDEO_FORMATS:
            return 'video'
        elif ext in DOC_FORMATS:
            return 'document'
        return 'unknown'

    def process(self, path_or_url: str) -> Dict:
        """Procesează conform tipului detectat"""
        input_type = self.detect_type(path_or_url)

        if input_type == 'url':
            return self.process_url(path_or_url)
        elif input_type == 'image':
            return self.process_image(path_or_url)
        elif input_type == 'audio':
            return self.process_audio(path_or_url)
        elif input_type == 'video':
            return self.process_video(path_or_url)
        elif input_type == 'document':
            return self.process_document(path_or_url)
        else:
            return {
                'input': path_or_url,
                'type': 'unknown',
                'status': 'FAILED',
                'message': f'Could not detect type for {path_or_url}'
            }

    def process_image(self, path: str) -> Dict:
        """Procesează imagine - extrage metadata + pattern recognition"""
        try:
            from PIL import Image
            img_available = True
        except ImportError:
            img_available = False

        p = Path(path)
        metadata = {
            'input': str(p),
            'type': 'image',
            'format': p.suffix.lower(),
            'size_bytes': p.stat().st_size,
            'hash': hashlib.md5(p.read_bytes()).hexdigest(),
            'processed_at': datetime.now().isoformat(),
            'status': 'OK'
        }

        if img_available:
            try:
                img = Image.open(p)
                metadata['dimensions'] = img.size
                metadata['mode'] = img.mode
                metadata['has_alpha'] = 'A' in img.mode
            except Exception as e:
                metadata['image_metadata_error'] = str(e)
        else:
            metadata['image_metadata_note'] = 'PIL not available'

        # Pattern recognition (basic)
        metadata['detected_patterns'] = self._detect_visual_patterns(p)

        self._save_metadata(metadata)
        return metadata

    def process_audio(self, path: str) -> Dict:
        """Procesează audio"""
        p = Path(path)
        metadata = {
            'input': str(p),
            'type': 'audio',
            'format': p.suffix.lower(),
            'size_bytes': p.stat().st_size,
            'hash': hashlib.md5(p.read_bytes()).hexdigest(),
            'processed_at': datetime.now().isoformat(),
            'status': 'OK',
            'transcription': None,
            'duration': None,
            'note': 'Audio transcription requires additional tools (whisper/faster-whisper)'
        }
        self._save_metadata(metadata)
        return metadata

    def process_video(self, path: str) -> Dict:
        """Procesează video"""
        p = Path(path)
        metadata = {
            'input': str(p),
            'type': 'video',
            'format': p.suffix.lower(),
            'size_bytes': p.stat().st_size,
            'hash': hashlib.md5(p.read_bytes()).hexdigest(),
            'processed_at': datetime.now().isoformat(),
            'status': 'OK',
            'duration': None,
            'frames_extracted': 0,
            'note': 'Video processing requires ffmpeg'
        }
        self._save_metadata(metadata)
        return metadata

    def process_document(self, path: str) -> Dict:
        """Procesează document - text extraction"""
        p = Path(path)
        metadata = {
            'input': str(p),
            'type': 'document',
            'format': p.suffix.lower(),
            'size_bytes': p.stat().st_size,
            'hash': hashlib.md5(p.read_bytes()).hexdigest(),
            'processed_at': datetime.now().isoformat(),
            'status': 'OK',
            'text_extracted': None,
            'structure': None
        }

        # Text extraction per format
        if p.suffix.lower() in {'.md', '.txt'}:
            try:
                metadata['text_extracted'] = p.read_text(encoding='utf-8')
                metadata['text_length'] = len(metadata['text_extracted'])
            except UnicodeDecodeError:
                metadata['text_extraction_error'] = 'encoding error'
        elif p.suffix.lower() == '.pdf':
            metadata['pdf_extraction_note'] = 'requires pypdf or pdftotext'
        elif p.suffix.lower() == '.docx':
            metadata['docx_extraction_note'] = 'requires python-docx'

        self._save_metadata(metadata)
        return metadata

    def process_url(self, url: str) -> Dict:
        """Procesează URL - fetch content"""
        import urllib.request
        metadata = {
            'input': url,
            'type': 'url',
            'url': url,
            'processed_at': datetime.now().isoformat(),
            'status': 'PENDING',
            'content': None
        }

        try:
            req = urllib.request.Request(
                url,
                headers={'User-Agent': 'SENTINEL_PRIME/1.0'}
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                metadata['status'] = 'OK'
                metadata['http_code'] = response.status
                metadata['content_type'] = response.headers.get('Content-Type', '')
                metadata['content_length'] = response.headers.get('Content-Length', '')
        except Exception as e:
            metadata['status'] = 'FAILED'
            metadata['error'] = str(e)

        self._save_metadata(metadata)
        return metadata

    def _detect_visual_patterns(self, image_path: Path) -> List[Dict]:
        """Detectează pattern-uri vizuale (basic implementation)"""
        # Acest nivel de pattern recognition depinde de model
        # Placeholder: returnează structura pentru analiză ulterioară

        patterns = []

        # Citire metadata pentru analiză
        try:
            file_hash = hashlib.md5(image_path.read_bytes()).hexdigest()
            patterns.append({
                'type': 'hash',
                'value': file_hash,
                'note': 'Use hash for matching with known patterns in 03_INTELLIGENCE/patterns/'
            })
        except Exception:
            pass

        # Lista de pattern-uri de verificat (manual sau cu ML)
        known_patterns = [
            {'name': 'dao_yin_yang', 'description': 'Yin-yang symbol with S-curve'},
            {'name': 'swastika', 'description': '4-armed hooked cross'},
            {'name': 'cross', 'description': 'Religious or secular cross'},
            {'name': 'spiral', 'description': 'Concentric spirals'},
            {'name': 'magna_schema', 'description': 'Orthodox monastic garment'}
        ]

        patterns.append({
            'type': 'candidates',
            'value': known_patterns,
            'note': 'Manual or ML-based verification needed'
        })

        return patterns

    def _save_metadata(self, metadata: Dict):
        """Salvează metadata în fișier"""
        try:
            current = json.loads(METADATA_FILE.read_text(encoding='utf-8'))
        except (json.JSONDecodeError, FileNotFoundError):
            current = []

        current.append(metadata)

        # Păstrează ultimele 1000 entries
        if len(current) > 1000:
            current = current[-1000:]

        METADATA_FILE.write_text(
            json.dumps(current, indent=2, ensure_ascii=False),
            encoding='utf-8'
        )

        self.processed.append(metadata)

    def get_processed_history(self) -> List[Dict]:
        """Returnează istoricul procesărilor"""
        return self.processed.copy()


def main():
    """Demo: multi-modal processor"""
    processor = MultiModalProcessor()

    print("=" * 60)
    print("SENTINEL Multi-Modal Processor Demo")
    print("=" * 60)

    # Test inputs
    test_inputs = [
        'C:\\Users\\apviz\\.minimax-agent\\projects\\SENTINEL_PRIME\\01_FOUNDATION\\doctrine\\A_FI_DOCTRINE.md',  # doc
        'https://en.wikipedia.org/wiki/Cucuteni%E2%80%93Trypillia_culture',  # URL
        # Adaugă alte teste când sunt disponibile imagini/audio/video
    ]

    for inp in test_inputs:
        input_type = processor.detect_type(inp)
        print(f"\n[INPUT] {inp}")
        print(f"[TYPE] {input_type}")
        result = processor.process(inp)
        print(f"[STATUS] {result.get('status')}")
        if 'size_bytes' in result:
            print(f"[SIZE] {result['size_bytes']} bytes")
        if 'format' in result:
            print(f"[FORMAT] {result['format']}")

    # Arată istoric
    history = processor.get_processed_history()
    print(f"\nProcessed in this session: {len(history)}")


if __name__ == '__main__':
    main()

