def detect_type(self, path_or_url: str) -> str:
    """
    Detectează tipul de input pe baza extensiei sau schemei URL.
    Type detection este sintactic — nu necesită existența fișierului.
    Existența se verifică abia la process() / process_image() / etc.
    """
    if path_or_url.startswith('http://') or path_or_url.startswith('https://'):
        return 'url'
    if path_or_url.startswith('file://') or path_or_url.startswith('data:'):
        return 'url'

    ext = Path(path_or_url).suffix.lower()
    if ext in IMAGE_FORMATS:
        return 'image'
    elif ext in AUDIO_FORMATS:
        return 'audio'
    elif ext in VIDEO_FORMATS:
        return 'video'
    elif ext in DOC_FORMATS:
        return 'document'

    # Dacă nu are extensie cunoscută dar nici nu e URL → necunoscut
    if not ext:
        return 'unknown'
    return 'unknown'

