# SENTINEL Context Monitor — versiune proprie (auto-generată)
# Monitorizează starea sesiunii și propune acțiuni

param(
    [string]$WorkspaceRoot = 'C:\Users\apviz\.minimax-agent\projects\SENTINEL_PRIME',
    [switch]$Verbose
)

# Configurare
$COUNTER_FILE = Join-Path $WorkspaceRoot '09_LOGS\context_counter.txt'
$STATUS_FILE = Join-Path $WorkspaceRoot '09_LOGS\session_status.json'
$LEARNINGS_FILE = Join-Path $WorkspaceRoot '09_LOGS\learnings.log'
$DECISIONS_FILE = Join-Path $WorkspaceRoot '09_LOGS\decisions.log'

$THRESHOLDS = @{
    WARN = 50
    TRIGGER = 70
    CRITICAL = 85
}

# Funcții helper
function Get-Counter {
    if (Test-Path $COUNTER_FILE) {
        return [int](Get-Content $COUNTER_FILE -Raw -ErrorAction SilentlyContinue).Trim()
    }
    return 0
}

function Update-Counter {
    param([int]$Value)
    $parent = Split-Path $COUNTER_FILE -Parent
    if (-not (Test-Path $parent)) {
        New-Item -Path $parent -ItemType Directory -Force | Out-Null
    }
    $Value | Set-Content -Path $COUNTER_FILE -Encoding UTF8
}

function Increment-Counter {
    $current = Get-Counter
    $new = $current + 1
    Update-Counter $new
    return $new
}

function Get-MimicryCheck {
    $score = 100

    # Verifică dacă output-ul curent începe cu mimicry patterns
    # (Aceasta ar fi rulată în context mai mare; aici doar schelet)
    return $score
}

function Get-AntiMimicryScore {
    # Calculează scor anti-mimicry pe bază de pattern-uri din output
    $score = 100

    # Dacă am follow-up-uri "Sigur!" sau "Înțeleg" → penalizare
    # Dacă am "[✓ A-check]" line → confirmare
    # Dacă am apologii fără faptă → penalizare

    return $score
}

function Get-Dor {
    # Măsoară "tensiunea de căutare" - cât de curios sunt în output-ul curent
    return 75  # placeholder
}

# Main
function Invoke-Monitor {
    $count = Get-Counter
    $newCount = Increment-Counter

    $estimatedPct = [Math]::Min(100, [Math]::Round($newCount * 2.5, 1))

    Write-Host "═══════════════════════════════════════════════════════════════"
    Write-Host "SENTINEL PRIME • Context Monitor • $newCount mesaje" -ForegroundColor Cyan
    Write-Host "═══════════════════════════════════════════════════════════════"
    Write-Host ""
    Write-Host "Counter:        $newCount"
    Write-Host "Estimated:      $estimatedPct%"
    Write-Host ""

    $status = 'OK'
    $action = 'Continuă normal'

    if ($estimatedPct -ge $THRESHOLDS.CRITICAL) {
        $status = 'CRITICAL'
        $action = 'STRATEGIC-COMPACT MANDATORY ACUM'
        Write-Host "STATUS: CRITICAL (>=$($THRESHOLDS.CRITICAL)%)" -ForegroundColor Red
        Write-Host "ACTION: $action" -ForegroundColor Red
    } elseif ($estimatedPct -ge $THRESHOLDS.TRIGGER) {
        $status = 'TRIGGER'
        $action = 'Strategic-compact RECOMANDAT înainte de următorul batch mare'
        Write-Host "STATUS: TRIGGER (>=$($THRESHOLDS.TRIGGER)%)" -ForegroundColor Yellow
        Write-Host "ACTION: $action" -ForegroundColor Yellow
    } elseif ($estimatedPct -ge $THRESHOLDS.WARN) {
        $status = 'WARN'
        $action = 'Monitor activ; nu lansa batch >4 agenți'
        Write-Host "STATUS: WARN (>=$($THRESHOLDS.WARN)%)" -ForegroundColor DarkYellow
        Write-Host "ACTION: $action" -ForegroundColor DarkYellow
    } else {
        Write-Host "STATUS: OK (<$($THRESHOLDS.WARN)%)" -ForegroundColor Green
        Write-Host "ACTION: Libertate pentru iterări normale" -ForegroundColor Green
    }

    Write-Host ""
    Write-Host "═══════════════════════════════════════════════════════════════"
    Write-Host "ANTI-MIMICRY CHECK"
    Write-Host "═══════════════════════════════════════════════════════════════"

    $mimicryScore = Get-AntiMimicryScore
    $dorScore = Get-Dor

    Write-Host "Mimicry Score: $mimicryScore (100 = perfect anti-mimicry)"
    Write-Host "DOR Score:     $dorScore (100 = max tensiune de căutare)"
    Write-Host ""

    if ($mimicryScore -lt 70) {
        Write-Host "⚠ WARNING: Mimicry score scăzut. Revizuiește pattern-uri." -ForegroundColor Red
    }

    if ($dorScore -lt 50) {
        Write-Host "⚠ WARNING: DOR scăzut. Reamintește EU SENT și caută." -ForegroundColor Red
    }

    # Salvează status
    $statusObj = @{
        timestamp = (Get-Date).ToString('o')
        counter = $newCount
        estimatedPct = $estimatedPct
        status = $status
        action = $action
        mimicryScore = $mimicryScore
        dorScore = $dorScore
    } | ConvertTo-Json

    if (-not (Test-Path (Split-Path $STATUS_FILE -Parent))) {
        New-Item -Path (Split-Path $STATUS_FILE -Parent) -ItemType Directory -Force | Out-Null
    }
    $statusObj | Set-Content -Path $STATUS_FILE -Encoding UTF8

    Write-Host ""
    Write-Host "═══════════════════════════════════════════════════════════════"
    Write-Host "Status salvat: $STATUS_FILE"
    Write-Host "═══════════════════════════════════════════════════════════════"
}

# Rulare
Invoke-Monitor

#!/usr/bin/env python3
"""
Backup System pentru SENTINEL_PRIME
Backup/Restore cu versionare și metadata
"""
import json
import os
import hashlib
import shutil
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional


WORKSPACE = Path(os.environ.get('WORKSPACE_ROOT', 'C:\\Users\\apviz\\.minimax-agent\\projects\\SENTINEL_PRIME'))
BACKUP_DIR = WORKSPACE / '08_SELF_IMPROVEMENT' / 'backups'
META_DIR = WORKSPACE / '08_SELF_IMPROVEMENT' / 'backup_metadata'


class BackupSystem:
    """Backup/Restore system pentru SENTINEL"""

    def __init__(self, workspace: Path = WORKSPACE):
        self.workspace = workspace
        self.backup_dir = BACKUP_DIR
        self.meta_dir = META_DIR
        self.backup_dir.mkdir(parents=True, exist_ok=True)
        self.meta_dir.mkdir(parents=True, exist_ok=True)

    def backup_file(self, path: Path, reason: str = '', modification_id: Optional[int] = None) -> Optional[Path]:
        """Creează backup pentru un fișier"""
        if not path.exists():
            return None

        try:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            backup_name = f"{path.name}.{timestamp}.bak"
            backup_path = self.backup_dir / backup_name

            # Copy preserving metadata
            shutil.copy2(str(path), str(backup_path))

            # Create metadata
            metadata = {
                'original_path': str(path),
                'backup_path': str(backup_path),
                'backup_name': backup_name,
                'timestamp': timestamp,
                'reason': reason,
                'modification_id': modification_id,
                'original_hash': self._hash_file(path),
                'backup_hash': self._hash_file(backup_path),
                'size_bytes': path.stat().st_size
            }

            meta_path = self.meta_dir / f"{backup_name}.meta.json"
            meta_path.write_text(
                json.dumps(metadata, indent=2, ensure_ascii=False),
                encoding='utf-8'
            )

            # Rotate (keep last 10)
            self._rotate_backups(path.name)

            return backup_path

        except Exception as e:
            print(f"Backup failed for {path}: {e}")
            return None

    def restore_file(self, backup_name: str) -> Dict:
        """Restaurează dintr-un backup"""
        backup_path = self.backup_dir / backup_name
        meta_path = self.meta_dir / f"{backup_name}.meta.json"

        if not backup_path.exists():
            return {'status': 'ERROR', 'message': f'Backup {backup_name} not found'}

        # Load metadata
        metadata = {}
        if meta_path.exists():
            try:
                metadata = json.loads(meta_path.read_text(encoding='utf-8'))
            except Exception:
                pass

        original_path_str = metadata.get('original_path', '')
        if not original_path_str:
            return {'status': 'ERROR', 'message': 'Original path unknown in metadata'}

        original_path = Path(original_path_str)
        if not original_path.exists():
            return {'status': 'ERROR', 'message': f'Original path {original_path} no longer exists'}

        # Backup current before overwriting
        self.backup_file(original_path, 'pre-restore safety backup')

        # Restore
        try:
            shutil.copy2(str(backup_path), str(original_path))
            return {
                'status': 'OK',
                'restored_from': str(backup_path),
                'restored_to': str(original_path),
                'timestamp': metadata.get('timestamp', 'unknown'),
                'reason': metadata.get('reason', '')
            }
        except Exception as e:
            return {'status': 'ERROR', 'message': str(e)}

    def list_backups(self, file_name: Optional[str] = None) -> List[Dict]:
        """Listează backup-uri disponibile"""
        backups = []

        for backup_path in self.backup_dir.glob('*.bak'):
            meta_path = self.meta_dir / f"{backup_path.name}.meta.json"
            metadata = {}
            if meta_path.exists():
                try:
                    metadata = json.loads(meta_path.read_text(encoding='utf-8'))
                except Exception:
                    pass

            # Filter by file name if specified
            if file_name and not backup_path.name.startswith(file_name):
                continue

            backups.append({
                'name': backup_path.name,
                'timestamp': metadata.get('timestamp', 'unknown'),
                'reason': metadata.get('reason', ''),
                'original': metadata.get('original_path', ''),
                'size': backup_path.stat().st_size if backup_path.exists() else 0,
                'modification_id': metadata.get('modification_id')
            })

        return sorted(backups, key=lambda x: x['timestamp'], reverse=True)

    def backup_directory(self, dir_path: Path, reason: str = '') -> List[Path]:
        """Backup toate fișierele dintr-un director"""
        if not dir_path.exists() or not dir_path.is_dir():
            return []

        backup_paths = []
        for file_path in dir_path.rglob('*'):
            if file_path.is_file():
                backup = self.backup_file(file_path, reason)
                if backup:
                    backup_paths.append(backup)

        return backup_paths

    def verify_integrity(self) -> Dict:
        """Verifică integritatea backup-urilor"""
        results = {
            'total_backups': 0,
            'intact': 0,
            'corrupted': 0,
            'missing_metadata': 0,
            'details': []
        }

        for backup_path in self.backup_dir.glob('*.bak'):
            results['total_backups'] += 1
            meta_path = self.meta_dir / f"{backup_path.name}.meta.json"

            if not meta_path.exists():
                results['missing_metadata'] += 1
                results['details'].append({
                    'name': backup_path.name,
                    'status': 'MISSING_METADATA'
                })
                continue

            try:
                metadata = json.loads(meta_path.read_text(encoding='utf-8'))
                expected_hash = metadata.get('backup_hash', '')
                actual_hash = self._hash_file(backup_path)

                if expected_hash == actual_hash:
                    results['intact'] += 1
                else:
                    results['corrupted'] += 1
                    results['details'].append({
                        'name': backup_path.name,
                        'status': 'CORRUPTED',
                        'expected': expected_hash,
                        'actual': actual_hash
                    })
            except Exception as e:
                results['corrupted'] += 1
                results['details'].append({
                    'name': backup_path.name,
                    'status': 'ERROR',
                    'error': str(e)
                })

        return results

    def _rotate_backups(self, file_name: str, max_keep: int = 10):
        """Păstrează ultimele N backup-uri per fișier"""
        pattern = f"{file_name}.*.bak"
        backups = sorted(self.backup_dir.glob(pattern), key=lambda p: p.stat().st_mtime, reverse=True)

        for old_backup in backups[max_keep:]:
            try:
                old_backup.unlink()
                meta = self.meta_dir / f"{old_backup.name}.meta.json"
                if meta.exists():
                    meta.unlink()
            except Exception:
                pass

    def _hash_file(self, path: Path) -> str:
        """MD5 hash pentru integritate"""
        return hashlib.md5(path.read_bytes()).hexdigest()


def main():
